    cin.tie(NULL);

    int n;
    cin >> n;

    int rightBoots[61] = {0};
    int leftBoots[61] = {0};

    for (int i = 0; i < n; i++) {
        int m;
        char l;
        cin >> m >> l;
        if (l == 'D') {
            rightBoots[m]++;
